MUK_st.name='MUK'; 
MUK_st.lat=29.440;
MUK_st.lon=79.62;
MUK_st.alt=2180;
MUK_st.env='Mt';
MUK_st.footp='Mx';
%%
MUK_rd=timetable(datetime(data_MUK(:,1:6)),data_MUK(:,18),data_MUK(:,13),data_MUK(:,20),data_MUK(:,19),data_MUK(:,21),'VariableNames',{'BsG','U','BaG','SSA','expA'});
%ask Rakesh for all wavelengths
%%

%import data from prod/pay/Actri.../data/MUK
a=zeros(51052,1);
aa=table2array(AbsCoeff7wavelengthsdata2005to2016forMC30102019(:,1:5));
t=[aa a];
AE=timetable(datetime(t));
AE.Ba1=AbsCoeff7wavelengthsdata2005to2016forMC30102019.b370nm;
AE.Ba2=AbsCoeff7wavelengthsdata2005to2016forMC30102019.b470nm;
AE.Ba3=AbsCoeff7wavelengthsdata2005to2016forMC30102019.b520nm;
AE.Ba4=AbsCoeff7wavelengthsdata2005to2016forMC30102019.b590nm;
AE.Ba5=AbsCoeff7wavelengthsdata2005to2016forMC30102019.b660nm;
AE.Ba6=AbsCoeff7wavelengthsdata2005to2016forMC30102019.b880nm;
AE.Ba7=AbsCoeff7wavelengthsdata2005to2016forMC30102019.b950nm;
AE.Var1=[];
AE_d=retime(AE,"daily",@nanmedian);

scat=MUK_rd;
scat.BaG=[];
scat.expA=[];
scat.SSA=[];

MUK_rd2=synchronize(scat,AE_d);
%%
datevec(MUK_rd2.Time(1))
datevec(MUK_rd2.Time(end))
prctile(MUK_rd2.U,[5 50 95])

plotFigControl(MUK_rd2,MUK_st.name); %[output:62f7c305] %[output:493e5076] %[output:31aa922e] %[output:6ef7b2d2] %[output:019cb250] %[output:16fc02c4] %[output:5f83d213] %[output:56d3c8d6] %[output:442db8a2] %[output:9b6f2951]
%%
lambdaSC=[450;550;700]*ones(1,4);
lambdaAE=[467;530;660]*ones(1,4);
lambdaAE7=[370 470 520 590 660 880 950];
MUK_cal=compute_exp_SSA(MUK_rd2,lambdaSC, lambdaAE); %[output:65f33791] %[output:1e3e6972] %[output:4ae29d8c] %[output:19a7b4f8] %[output:5df9c5ca] %[output:13b94766] %[output:5b6d13ef] %[output:6a57aafd] %[output:1b3856ad] %[output:06842faa] %[output:363fa504] %[output:82a2ada5] %[output:0d0065a7] %[output:5d9eb3ea] %[output:7dc54d14] %[output:6409886e] %[output:55a0e47e] %[output:8c0a5822] %[output:097ad630] %[output:6d5dde87] %[output:317068fc] %[output:4361afd2] %[output:877c446a] %[output:76b4f014] %[output:3bfc1cc3] %[output:3a81d20c] %[output:56f93a6c] %[output:7715f607]
%%
MUK_cal.SSA=MUK_rd2.BsG./(MUK_rd2.BsG+MUK_rd2.Ba3);
plotFigControl_cal(MUK_cal, MUK_st.name); %[output:341b6345] %[output:8d0587dd] %[output:9e7de72f]
%%
MUK_tr=MUK_rd2;
MUK_tr.y=year(MUK_tr.Time);
%begin: 2006, end 2013 --> 8y but only station in India
P=timerange('2006-01-01','2016-01-01');
MUK_tr=MUK_tr(P,:);

p1=timerange('2014-01-01','2016-01-01');
MUK_tr.BsG(p1)=NaN;
MUK_cal2=compute_exp_SSA(MUK_tr,lambdaSC, lambdaAE); %[output:6ca71464] %[output:589a4e41] %[output:2a51f62e] %[output:4ba65321] %[output:40154002] %[output:6ae2808b] %[output:82ea5404] %[output:880c4daa] %[output:897050a6] %[output:664fd065] %[output:5460498b] %[output:7813fe75] %[output:9b7ee171] %[output:203bbabc] %[output:5aac273a] %[output:33f0d0b4] %[output:1099c56e] %[output:136965bc] %[output:7769c025] %[output:4a081134] %[output:2e722a6a] %[output:6c0529b1] %[output:8ff22b5b] %[output:6943f830] %[output:8eab5fe4]
MUK_cal2.SSA=MUK_tr.BsG./(MUK_tr.BsG+MUK_tr.Ba3);

MUK_tr=outerjoin(MUK_tr,MUK_cal2);
%just use all

% use only Ba3
MUK_tr.Ba1=[];
MUK_tr.Ba2=[];
MUK_tr.Ba4=[];
MUK_tr.Ba5=[];
MUK_tr.Ba6=[];
MUK_tr.Ba7=[];

%use only exA_fit
MUK_tr.expA_bg=[];
MUK_tr.expA_br=[];
MUK_tr.expA_gr=[];

%%
MUK_result=all_trend_STN(MUK_tr,MUK_st); 
%%
MUK_result_D=MUK_result;

